package converter

import (
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

func TestFindPython_ExplicitPathSucceeds(t *testing.T) {
	skipOnWindows(t)
	py := makeFakePython(t, "python-ok", 0, "")
	c := &Converter{cfg: &Config{PythonPath: py}}

	got, err := c.findPython()
	if err != nil {
		t.Fatalf("findPython: %v", err)
	}
	if got != py {
		t.Errorf("findPython() = %q, want %q", got, py)
	}
}

func TestFindPython_ExplicitPathFailsPrecheck(t *testing.T) {
	skipOnWindows(t)
	py := makeFakePython(t, "python-no-playwright", 1,
		"ModuleNotFoundError: No module named 'playwright'")
	c := &Converter{cfg: &Config{PythonPath: py}}

	_, err := c.findPython()
	if err == nil {
		t.Fatal("expected error from explicit path that cannot import playwright")
	}
	msg := err.Error()
	if !strings.Contains(msg, py) {
		t.Errorf("error should reference interpreter path %q, got: %v", py, err)
	}
	if !strings.Contains(msg, "playwright") {
		t.Errorf("error should mention playwright, got: %v", err)
	}
}

func TestFindPython_ExplicitPathNonexistent(t *testing.T) {
	c := &Converter{cfg: &Config{PythonPath: "/no/such/python-binary"}}

	if _, err := c.findPython(); err == nil {
		t.Fatal("expected error for nonexistent explicit python path")
	}
}

func TestFindPython_AutoDetectSkipsInterpreterMissingPlaywright(t *testing.T) {
	skipOnWindows(t)
	stubExtraPythonCandidates(t, nil)
	dir := t.TempDir()
	writeShellScript(t, filepath.Join(dir, "python3"), 1,
		"ModuleNotFoundError: No module named 'playwright'")
	t.Setenv("PATH", dir)

// md2pdf converts Markdown files to PDF with GitHub-style design.
//
// It renders Mermaid diagrams, supports Noto Sans CJK JP font for Japanese text,
// and uses a headless Chromium browser for high-fidelity PDF output.
//
// Usage:
//
//	md2pdf [options] <input.md>
//
// Examples:
//
//	md2pdf document.md
//	md2pdf -o output.pdf document.md
//	md2pdf -font /usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc document.md
package main

import (
	"fmt"
	"os"

	"github.com/135yshr/md2pdf/internal/converter"
)

var (
	version = "dev"
	commit  = "none"
	date    = "unknown"
)

func main() {
	cfg, err := parseFlags(os.Args[1:])
	if err != nil {
		fmt.Fprintf(os.Stderr, "md2pdf: %v\n", err)
		printUsage()
		os.Exit(1)
	}

	c, err := converter.New(cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "md2pdf: failed to initialize converter: %v\n", err)
		os.Exit(1)
	}
	defer c.Close()

	fmt.Printf("Converting %s ...\n", cfg.InputFile)
	if err := c.Convert(cfg.InputFile, cfg.OutputFile); err != nil {
		fmt.Fprintf(os.Stderr, "md2pdf: conversion failed: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("PDF saved to %s\n", cfg.OutputFile)
}

